-- The two checklists published on 2026-10-09: the first week in a new job
-- (Work) and an unexpected rejection (Setbacks).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-09`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('your-first-week-in-a-new-job', 'Your First Week in a New Job', 'For the week you start somewhere new, when everybody else knows how things work and you do not. It helps you learn names, ask the questions that feel too basic to ask later, and judge yourself on the right things for a while.', 'Work', '["Write down names and roles the day you hear them — nobody minds the notebook in week one.", "Ask the basic questions now, not in a month — week one is the only free pass you get.", "Find out what your manager counts as a good first month — you cannot hit a target nobody named.", "Book a short chat with two people on your team — the work makes sense once the people do.", "Keep a list of what confused you today — it becomes the handover for the next new person.", "Leave on time at least three days this week — early overtime sets an expectation you keep.", "Judge yourself on learning, not output — contributing comes after understanding.", "Tell someone at home how it is going — a new job is tiring in a way that surprises people."]'::jsonb, 'as needed', array['Work', 'Life Transitions']::text[], 1, '2026-10-09T16:00:00+00:00'::timestamptz),
  ('after-a-rejection-you-did-not-expect', 'After a Rejection You Did Not Expect', 'For the hours after a no you were not braced for, from a job, an application or a person. It helps you get through the first evening, keep the no from spreading into a verdict on you, and work out what, if anything, to do next.', 'Setbacks', '["Say the sentence plainly to yourself once — vague bad news keeps growing in the dark.", "Hold off replying for a day — the first draft is written by the sting.", "Tell one person the same evening — a no kept private gets bigger overnight.", "Write what this no is actually about — one decision by one person is not a verdict on you.", "Name one thing you did well regardless — the outcome does not grade the effort.", "Eat and sleep as normally as you can manage — a bad night makes tomorrow''s version worse.", "Ask for feedback once, then let it be — one ask is useful, three is picking at it.", "Pick the next small step for later in the week — not tonight, and not nothing."]'::jsonb, 'as needed', array['Self-Esteem', 'Resilience']::text[], 1, '2026-10-09T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
